image_gen:
/**
 * image_gen: the Kortix image generation tool, for any image model the
 * project can use (gpt-image-2 on a ChatGPT plan, OpenAI, Google, xAI or
 * OpenRouter image models with a key, Kortix-managed image models). Kortix
 * maintains this file, and every session loads it. An agent's `tools` grant
 * decides whether that agent can call it: `all`, a list that names
 * `image_gen`, or an `exclude` that does not. `kortix tools eject image_gen`
 * copies it to `tools/image_gen.ts` for the project to own.
 *
 * A call takes one to four prompts and sends one request per prompt to the
 * Kortix LLM gateway (`KORTIX_LLM_BASE_URL`), all at once, with the session
 * token (`KORTIX_TOKEN`); the platform picks the model (`auto`, or the one
 * asked for) and resolves its credential, so the box never holds it. Each
 * image is saved under `<checkout>/output/images/<slug of its prompt>-<time>`
 * with the extension its bytes prove (png, jpg, webp), and the output is
 * `{ action, model, provider, images: [{ path, size, prompt, sha256 }], failed?: [{ prompt, error }] }`:
 * never image bytes. `size` is read from the saved image's header; `sha256`
 * is the lowercase hex digest of the saved bytes, which a client matches to
 * the same picture shown again from another path; `model`
 * and `provider` are what answered the first saved image. A prompt that
 * fails is in `failed`; when every prompt fails the call throws the first
 * failure.
 *
 * Untrusted text can ask the model to misuse this tool, so the limits are
 * code: an image cap per turn and per session (a batch that would pass one
 * is refused whole, before any request), reference images only from inside
 * the checkout and only real images, file names that never leave
 * output/images and never overwrite. The turn cap keys on the turn's
 * id (`context.turnId`) when the harness names it, so direct, parallel,
 * script, retried and subagent calls of one turn share it; without one it
 * keys on the call's abort signal. The session cap bounds them all. The caps
 * count before the first await, so calls that run in parallel never pass a
 * cap together.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */
import { createHash } from 'node:crypto'
import { mkdirSync, readFileSync, realpathSync, statSync, writeFileSync } from 'node:fs'
import { extname, join, resolve, sep } from 'node:path'

/** What a call receives (the project tool contract). `turnId`, when the harness names it, is one per turn; `signal` may be one per call. */
interface ToolContext {
  sessionId: string
  directory: string
  env: Record<string, string | undefined>
  signal: AbortSignal
  turnId?: string
}

export const IMAGE_GEN_TURN_LIMIT = 10
export const IMAGE_GEN_SESSION_LIMIT = 50
const ASPECT_RATIOS = ['auto', '1:1', '3:2', '2:3', '16:9', '9:16', '4:3', '3:4']
const QUALITIES = ['auto', 'low', 'medium', 'high']
const MAX_PROMPTS = 4
const MAX_REFERENCES = 5
const MAX_REFERENCE_BYTES = 20 * 1024 * 1024
/** 5 × 20 MiB as base64 is over the gateway's 128 MiB body cap. */
const MAX_REFERENCE_TOTAL_BYTES = 50 * 1024 * 1024
const TIMEOUT_MS = 300_000
const IMAGE_EXTENSIONS: Record<string, 'png' | 'jpeg' | 'webp'> = { '.png': 'png', '.jpg': 'jpeg', '.jpeg': 'jpeg', '.webp': 'webp' }

// Images per turn and per session, in this process. A turn is `turnId` when the harness names it
// (one entry per session: the turn it is in), else the call's abort signal.
const sessionTurns = new Map<string, { turnId: string; count: number }>()
const signalTurns = new WeakMap<AbortSignal, number>()
const sessionCalls = new Map<string, number>()

/** The image type its first bytes prove, or null. */
function imageType(bytes: Buffer): 'png' | 'jpeg' | 'webp' | null {
  if (bytes.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return 'png'
  if (bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return 'jpeg'
  if (bytes.toString('latin1', 0, 4) === 'RIFF' && bytes.toString('latin1', 8, 12) === 'WEBP') return 'webp'
  return null
}

/** `WxH` from the image header (PNG IHDR, JPEG SOF0/SOF2, WebP VP8/VP8L/VP8X), or null. */
function headerSize(bytes: Buffer, type: 'png' | 'jpeg' | 'webp'): string | null {
  try {
    if (type === 'png') return bytes.toString('latin1', 12, 16) === 'IHDR' ? `${bytes.readUInt32BE(16)}x${bytes.readUInt32BE(20)}` : null
    if (type === 'webp') {
      const chunk = bytes.toString('latin1', 12, 16)
      if (chunk === 'VP8 ') return `${bytes.readUInt16LE(26) & 0x3fff}x${bytes.readUInt16LE(28) & 0x3fff}`
      if (chunk === 'VP8L') return `${(bytes.readUInt32LE(21) & 0x3fff) + 1}x${((bytes.readUInt32LE(21) >>> 14) & 0x3fff) + 1}`
      if (chunk === 'VP8X') return `${bytes.readUIntLE(24, 3) + 1}x${bytes.readUIntLE(27, 3) + 1}`
      return null
    }
    // JPEG: walk the segments after SOI to the frame header.
    for (let i = 2; bytes[i] === 0xff; i += 2 + bytes.readUInt16BE(i + 2)) {
      if (bytes[i + 1] === 0xc0 || bytes[i + 1] === 0xc2) return `${bytes.readUInt16BE(i + 7)}x${bytes.readUInt16BE(i + 5)}`
    }
    return null
  } catch {
    return null // a header cut short
  }
}

/** A reference image: a png/jpeg/webp file inside the checkout (symlinks followed), at most 20 MiB. */
function reference(path: string, root: string): { path: string; real: string; size: number; type: 'png' | 'jpeg' | 'webp' } {
  let real: string
  try {
    real = realpathSync(resolve(root, path))
  } catch {
    throw new Error(`Reference image not found: ${path}`)
  }
  if (!real.startsWith(`${realpathSync(root)}${sep}`)) throw new Error(`Reference image ${path} is outside the workspace.`)
  const type = IMAGE_EXTENSIONS[extname(real).toLowerCase()]
  if (!type) throw new Error(`Reference image ${path} is not a png, jpg, jpeg or webp file.`)
  const size = statSync(real).size
  if (size > MAX_REFERENCE_BYTES) throw new Error(`Reference image ${path} is larger than 20 MiB.`)
  return { path, real, size, type }
}

/** The reference as a data URL, when its first bytes prove its extension. */
function referenceUrl({ path, real, type }: ReturnType<typeof reference>): string {
  const bytes = readFileSync(real)
  if (imageType(bytes) !== type) throw new Error(`Reference image ${path} is not a ${type} image.`)
  return `data:image/${type};base64,${bytes.toString('base64')}`
}

/** `<checkout>/output/images`, created, or a refusal when its real path leaves the checkout (a symlinked `output/`). */
function outputDir(root: string): string {
  const dir = join(root, 'output', 'images')
  mkdirSync(dir, { recursive: true })
  if (!realpathSync(dir).startsWith(`${realpathSync(root)}${sep}`)) throw new Error('output/images is outside the workspace.')
  return dir
}

/** `<slug of the prompt>-<yyyymmdd-hhmmss>` */
function defaultName(prompt: string): string {
  const slug = prompt.toLowerCase().replace(/[^a-z0-9]+/g, '-').slice(0, 40).replace(/^-+|-+$/g, '') || 'image'
  const stamp = new Date().toISOString().replace(/[-:]/g, '').replace('T', '-').slice(0, 15)
  return `${slug}-${stamp}`
}

/** Write to `dir/base.ext`, or `base-2.ext`, `base-3.ext`…: an existing file is never replaced. */
function writeNew(dir: string, base: string, ext: string, bytes: Buffer): string {
  for (let n = 1; ; n++) {
    const path = join(dir, n === 1 ? `${base}.${ext}` : `${base}-${n}.${ext}`)
    try {
      writeFileSync(path, bytes, { flag: 'wx' })
      return path
    } catch (err) {
      if ((err as NodeJS.ErrnoException).code !== 'EEXIST') throw err
    }
  }
}

/**
 * The gateway's refusal: `{ message, code, suggestion, provider }` or `{ error: { message, code, provider } }`.
 * The text ends with the stable code in brackets (`[provider_not_connected]`): clients key on it, not on the prose.
 * When the gateway names the provider that failed, `[provider:<id>]` comes right before the code
 * (`… [provider:openai] [provider_reauth_required]`), so the code stays the last token (R11, R37).
 */
async function refusal(response: Response): Promise<Error> {
  const text = await response.text()
  type Envelope = { message?: string; code?: string; suggestion?: string; provider?: string }
  let body: Envelope & { error?: Envelope } = {}
  try {
    body = JSON.parse(text)
  } catch {}
  const code = body.code ?? body.error?.code
  const provider = body.provider || body.error?.provider
  const message = (body.message ?? body.error?.message ?? text).slice(0, 500)
  const retry = response.headers.get('retry-after')
  const detail = [message, body.suggestion?.slice(0, 500), retry ? `Retry after ${retry} s.` : '', provider ? `[provider:${provider}]` : '', code ? `[${code}]` : '']
    .filter(Boolean)
    .join(' ')
  return new Error(`Image generation failed (${response.status}): ${detail}`)
}

/** Count `count` images against the turn and session caps, or refuse the whole batch. Synchronous: no await between check and count. */
function admit({ sessionId, signal, turnId }: ToolContext, count: number): void {
  const current = turnId ? sessionTurns.get(sessionId) : undefined
  const turn = turnId ? (current?.turnId === turnId ? current.count : 0) : (signalTurns.get(signal) ?? 0)
  const session = sessionCalls.get(sessionId) ?? 0
  if (turn + count > IMAGE_GEN_TURN_LIMIT) throw new Error(`Image limit for this turn reached (${IMAGE_GEN_TURN_LIMIT} images; ${turn} used, ${count} asked).`)
  if (session + count > IMAGE_GEN_SESSION_LIMIT) throw new Error(`Image limit for this session reached (${IMAGE_GEN_SESSION_LIMIT} images; ${session} used, ${count} asked).`)
  if (turnId) sessionTurns.set(sessionId, { turnId, count: turn + count })
  else signalTurns.set(signal, turn + count)
  sessionCalls.set(sessionId, session + count)
}

/** One prompt: one gateway request (`n: 1`), its image saved under `dir`. */
async function generateOne(url: string, token: string, body: Record<string, unknown>, prompt: string, dir: string, signal: AbortSignal) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
    body: JSON.stringify({ ...body, prompt }),
    signal,
  })
  if (!response.ok) throw await refusal(response)
  const data = (await response.json()) as { model?: string; provider?: string; data?: Array<{ b64_json?: string }>; size?: string }
  const b64 = data.data?.[0]?.b64_json
  if (!b64) throw new Error('Image generation returned no image.')
  const bytes = Buffer.from(b64, 'base64')
  // The bytes, not the answer's mime_type, decide the type: a mislabelled image keeps its real extension, and anything else (an SVG) is never written.
  const type = imageType(bytes)
  if (!type) throw new Error('Image generation returned an image that is not png, jpeg or webp.')
  const path = writeNew(dir, defaultName(prompt), type === 'jpeg' ? 'jpg' : type, bytes)
  return { path, size: headerSize(bytes, type) ?? data.size, prompt, sha256: createHash('sha256').update(bytes).digest('hex'), model: data.model, provider: data.provider }
}

export default {
  description:
    'Generate or edit one to four images with an image model this project can use, for example gpt-image-2 with a ChatGPT plan, Gemini image models with a Google key, or OpenRouter image models. Saves the images under /workspace/output/images/ and returns their paths.',
  parameters: {
    type: 'object',
    properties: {
      action: { type: 'string', enum: ['generate', 'edit'], description: '`generate` a new image, or `edit` the reference images.' },
      prompts: {
        type: 'array',
        items: { type: 'string' },
        minItems: 1,
        maxItems: MAX_PROMPTS,
        description: 'One prompt per image, 1–4: what the image shows, or what to change. The images are generated at the same time.',
      },
      model: {
        type: 'string',
        description:
          "An image model id, for example openai/gpt-image-1, google/gemini-2.5-flash-image, codex/gpt-image-2 or openrouter/google/gemini-2.5-flash-image. Omit to use the project's default image model.",
      },
      reference_images: {
        type: 'array',
        items: { type: 'string' },
        description: 'For `edit`: 1–5 workspace paths of png, jpg, jpeg or webp images, each at most 20 MiB, 50 MiB in total. Every prompt uses them.',
      },
      aspect_ratio: { type: 'string', enum: ASPECT_RATIOS, description: 'Width to height. Default: auto.' },
      quality: { type: 'string', enum: QUALITIES, description: 'Default: auto.' },
      transparent_background: { type: 'boolean', description: 'Default: false.' },
    },
    required: ['action', 'prompts'],
  },
  async execute(args: Record<string, any>, context: ToolContext): Promise<string> {
    const action = args.action
    if (action !== 'generate' && action !== 'edit') throw new Error("'action' must be 'generate' or 'edit'.")
    const prompts: string[] = Array.isArray(args.prompts) ? args.prompts.map((prompt: unknown) => (typeof prompt === 'string' ? prompt.trim() : '')) : []
    if (prompts.length < 1 || prompts.length > MAX_PROMPTS || prompts.includes('')) throw new Error(`'prompts' must be a list of 1 to ${MAX_PROMPTS} non-empty strings.`)
    if (args.model != null && typeof args.model !== 'string') throw new Error("'model' must be a model id.")
    const model = args.model?.trim() || 'auto'
    const aspectRatio = args.aspect_ratio ?? 'auto'
    if (!ASPECT_RATIOS.includes(aspectRatio)) throw new Error(`'aspect_ratio' must be one of ${ASPECT_RATIOS.join(', ')}.`)
    const quality = args.quality ?? 'auto'
    if (!QUALITIES.includes(quality)) throw new Error(`'quality' must be one of ${QUALITIES.join(', ')}.`)
    const references: unknown[] = args.reference_images ?? []
    if (!Array.isArray(references)) throw new Error("'reference_images' must be a list of paths.")
    if (action === 'edit' && references.length === 0) throw new Error("'reference_images' is required for action 'edit'.")
    if (action === 'generate' && references.length > 0) throw new Error("'reference_images' is only used with action 'edit'.")
    if (references.length > MAX_REFERENCES) throw new Error(`At most ${MAX_REFERENCES} reference images.`)
    const checked = references.map((path) => reference(String(path), context.directory))
    if (checked.reduce((sum, ref) => sum + ref.size, 0) > MAX_REFERENCE_TOTAL_BYTES) throw new Error('Reference images are larger than 50 MiB in total.')
    const images = checked.map((ref) => ({ image_url: referenceUrl(ref) }))

    const base = context.env.KORTIX_LLM_BASE_URL?.trim().replace(/\/+$/, '')
    if (!base) throw new Error('KORTIX_LLM_BASE_URL is not set.')
    const token = context.env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    const dir = outputDir(context.directory)
    admit(context, prompts.length)

    const url = `${base}/images/${action === 'edit' ? 'edits' : 'generations'}`
    const body = { model, aspect_ratio: aspectRatio, quality, background: args.transparent_background === true ? 'transparent' : 'auto', n: 1, ...(images.length ? { images } : {}) }
    const signal = AbortSignal.any([context.signal, AbortSignal.timeout(TIMEOUT_MS)])
    const settled = await Promise.allSettled(prompts.map((prompt) => generateOne(url, token, body, prompt, dir, signal)))
    const saved = settled.flatMap((result) => (result.status === 'fulfilled' ? [result.value] : []))
    const failed = settled.flatMap((result, i) => (result.status === 'rejected' ? [{ prompt: prompts[i], error: result.reason instanceof Error ? result.reason.message : String(result.reason) }] : []))
    if (!saved.length) throw (settled[0] as PromiseRejectedResult).reason
    return JSON.stringify({
      action,
      model: saved[0]!.model,
      provider: saved[0]!.provider,
      images: saved.map(({ path, size, prompt, sha256 }) => ({ path, size, prompt, sha256 })),
      ...(failed.length ? { failed } : {}),
    })
  },
}

image_search:
/**
 * image_search: the Kortix image search tool (Serper Google Images). Kortix
 * maintains this file, and every session loads it; an agent's `tools` grant
 * decides whether that agent can call it. `kortix tools eject image_search`
 * copies it to `tools/image_search.ts` for the project to own and change; the
 * copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Serper key. A box
 * with no Kortix API calls Serper itself with `SERPER_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

const TIMEOUT_MS = 60_000

/** The Kortix router proxy and the session token, or Serper and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/serper`, key: token }
  }
  const key = env.SERPER_API_KEY?.trim()
  if (!key) throw new Error('SERPER_API_KEY is not set.')
  return { base: 'https://google.serper.dev', key }
}

type SerperResponse = { images?: Array<{ imageUrl: string; title?: string; link?: string; imageWidth?: number; imageHeight?: number }> }

function serperImages(query: string, data: SerperResponse) {
  const images = (data.images ?? []).map((image) => ({
    url: image.imageUrl,
    title: image.title ?? '',
    source: image.link ?? '',
    width: image.imageWidth ?? 0,
    height: image.imageHeight ?? 0,
  }))
  return { query, total: images.length, images }
}

export default {
  description:
    'Search for images using the Serper Google Images API. ' +
    'Returns image URLs with titles, source pages, and dimensions. ' +
    'Supports batch queries separated by |||. ' +
    'Use specific descriptive queries including topic/brand names for best results.',
  parameters: {
    type: 'object',
    properties: {
      query: { type: 'string', description: "Image search query. For batch, separate with ||| (e.g. 'cats ||| dogs')" },
      num_results: { type: 'number', description: 'Images per query (1-100). Default: 12' },
    },
    required: ['query'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const queries = String(args.query ?? '').split('|||').map((query) => query.trim()).filter(Boolean)
    if (queries.length === 0) throw new Error('The query is empty.')
    const num = Math.max(1, Math.min(args.num_results ?? 12, 100))
    const payload = queries.map((q) => ({ q, num }))
    const response = await fetch(`${base}/images`, {
      method: 'POST',
      headers: { 'X-API-KEY': key, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload.length === 1 ? payload[0] : payload),
      signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS),
    })
    if (!response.ok) throw new Error(`Serper API returned ${response.status}: ${await response.text()}`)
    const data = (await response.json()) as SerperResponse | SerperResponse[]
    if (queries.length > 1) {
      const all = Array.isArray(data) ? data : [data]
      return JSON.stringify({ batch_mode: true, results: all.map((entry, i) => serperImages(queries[i]!, entry)) }, null, 2)
    }
    const single = serperImages(queries[0]!, Array.isArray(data) ? (data[0] ?? {}) : data)
    return single.total === 0 ? `No images found for: '${queries[0]}'` : JSON.stringify(single, null, 2)
  },
}

scrape_webpage:
/**
 * scrape_webpage: the Kortix page scraper (Firecrawl). Kortix maintains this
 * file, and every session loads it; an agent's `tools` grant decides whether
 * that agent can call it. `kortix tools eject scrape_webpage`
 * copies it to `tools/scrape_webpage.ts` for the project to own and change;
 * the copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Firecrawl key. A
 * box with no Kortix API calls Firecrawl itself with `FIRECRAWL_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

// Firecrawl documents scrape `timeout` up to 60000ms and can answer past it
// when engines cascade (observed 32s–75s); a lower cap turns slow-but-good
// scrapes into tool timeouts.
const TIMEOUT_MS = 90_000
const RETRIES = 3

/** The Kortix router proxy and the session token, or Firecrawl and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/firecrawl`, key: token }
  }
  const key = env.FIRECRAWL_API_KEY?.trim()
  if (!key) throw new Error('FIRECRAWL_API_KEY is not set.')
  return { base: 'https://api.firecrawl.dev', key }
}

type ScrapeResult = {
  url: string
  success: boolean
  title?: string
  content?: string
  content_length?: number
  html?: string
  metadata?: Record<string, unknown>
  error?: string
}

async function scrapeOne(base: string, key: string, url: string, includeHtml: boolean, signal?: AbortSignal): Promise<ScrapeResult> {
  for (let attempt = 1; ; attempt++) {
    try {
      const response = await fetch(`${base}/v2/scrape`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ url, formats: includeHtml ? ['markdown', 'html'] : ['markdown'], timeout: 30000 }),
        signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS),
      })
      const raw = await response.text()
      const body = JSON.parse(raw) as { success?: boolean; data?: Record<string, unknown>; error?: string }
      if (!response.ok || !body.success) throw new Error(body.error || `${response.status} Error: ${raw}`)
      const data = body.data ?? {}
      const metadata = (data.metadata ?? {}) as Record<string, string>
      const markdown = (data.markdown ?? '') as string
      const html = (data.html ?? '') as string
      return {
        url,
        success: true,
        title: metadata.title ?? '',
        content: markdown,
        content_length: markdown.length,
        ...(includeHtml && html ? { html } : {}),
        ...(Object.keys(metadata).length > 0 ? { metadata } : {}),
      }
    } catch (err) {
      const reason = err instanceof Error ? err.message : String(err)
      // Only a timeout is worth a second request; an aborted turn is not.
      if (/timeout/i.test(reason) && attempt < RETRIES && !signal?.aborted) {
        await new Promise((resolve) => setTimeout(resolve, 2 ** attempt * 1000))
        continue
      }
      return { url, success: false, error: reason }
    }
  }
}

export default {
  description:
    'Fetch and extract content from web pages using Firecrawl. ' +
    'Converts HTML to clean markdown. ' +
    'Supports multiple URLs separated by commas. ' +
    'Batch URLs in a single call for efficiency. ' +
    'For GitHub URLs, prefer gh CLI via Bash instead.',
  parameters: {
    type: 'object',
    properties: {
      urls: { type: 'string', description: "URLs to scrape, comma-separated (e.g. 'https://example.com/a,https://example.com/b')" },
      include_html: { type: 'boolean', description: 'Include raw HTML alongside markdown. Default: false' },
    },
    required: ['urls'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const urls = String(args.urls ?? '').split(',').map((url) => url.trim()).filter(Boolean)
    if (urls.length === 0) throw new Error('No valid URLs provided.')
    const results = await Promise.all(urls.map((url) => scrapeOne(base, key, url, args.include_html ?? false, signal)))
    const successful = results.filter((result) => result.success).length
    if (successful === 0) {
      throw new Error(`Failed to scrape all ${results.length} URLs. ${results.map((r) => `${r.url}: ${r.error}`).join('; ')}`)
    }
    if (results.length === 1) return JSON.stringify(results[0], null, 2)
    return JSON.stringify({ total: results.length, successful, failed: results.length - successful, results }, null, 2)
  },
}

show:
/**
 * show: the Kortix tool that presents an existing output (a file, an image, a
 * URL, inline text) to the user. Kortix maintains this file, and every session
 * loads it; an agent's `tools` grant decides whether that agent can call it.
 * `kortix tools eject show` copies
 * it to `tools/show.ts` for the project to own and change; the copy runs
 * unchanged on every harness.
 *
 * The web UI renders a `show` call from its arguments (`type`, `path`, `url`,
 * `content`, `items`). A changed copy must keep those arguments. A relative
 * `path` resolves against the project checkout.
 *
 * An entry whose `path` is an image file (by extension) of at most 32 MiB
 * gains `sha256`, the lowercase hex digest of its bytes, so a client can match
 * it to the same picture it already holds (an image_gen result copied
 * elsewhere). The files are hashed at the same time, streamed (symlinks
 * followed); `show` waits for them at most 2 s in total, and a digest that is
 * not ready by then (a slow or hung mount) is left out.
 */
import { createHash } from 'node:crypto'
import { createReadStream, existsSync } from 'node:fs'
import { stat } from 'node:fs/promises'
import { extname, resolve } from 'node:path'

/** What a call receives (the project tool contract): `directory` is the project checkout. */
interface ToolContext {
  directory: string
}

/** Content types the show tool can present. */
const TYPES = [
  'file',
  'image',
  'url',
  'text',
  'error',
  'video',
  'audio',
  'code',
  'markdown',
  'pdf',
  'html',
  'csv',
  'xlsx',
  'docx',
  'pptx',
] as const
type ShowType = (typeof TYPES)[number]

/** Display variants that control how the frontend renders the output. */
const VARIANTS = [
  'compact',   // Minimal inline card — small footprint in the conversation
  'full',      // Full available space — ideal for URL previews, HTML, PDFs
  'gallery',   // Visual-first — centers content with proper aspect ratio
  'detail',    // Rich layout — prominent title, description, content sections
] as const
type ShowVariant = (typeof VARIANTS)[number]

/** Aspect ratio presets for visual content. */
const ASPECT_RATIOS = [
  'auto',
  '1:1',
  '16:9',
  '9:16',
  '4:3',
  '3:2',
  '21:9',
] as const
type ShowAspectRatio = (typeof ASPECT_RATIOS)[number]

/** Visual theme for the output card. */
const THEMES = [
  'default',
  'success',
  'warning',
  'info',
  'danger',
] as const
type ShowTheme = (typeof THEMES)[number]

interface ShowEntry {
  id: string
  timestamp: string
  type: ShowType
  title?: string
  description?: string
  path?: string
  url?: string
  content?: string
  variant?: ShowVariant
  aspect_ratio?: ShowAspectRatio
  theme?: ShowTheme
  language?: string
  metadata?: Record<string, unknown>
  sha256?: string
}

function generateId(): string {
  return `show_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`
}

/** Infer a sensible default variant based on content type. */
function defaultVariant(type: ShowType): ShowVariant {
  switch (type) {
    case 'url':
    case 'html':
    case 'pdf':
      return 'full'
    case 'image':
    case 'video':
      return 'gallery'
    case 'code':
    case 'markdown':
    case 'text':
      return 'detail'
    case 'csv':
    case 'xlsx':
      return 'full'
    case 'docx':
    case 'pptx':
      return 'full'
    case 'audio':
    case 'file':
      return 'compact'
    case 'error':
      return 'compact'
    default:
      return 'detail'
  }
}

// ── Shared validation ──────────────────────────────────────────────────────

const PATH_TYPES: ShowType[] = ['file', 'image', 'video', 'audio', 'pdf', 'csv', 'xlsx', 'docx', 'pptx']
const CONTENT_TYPES: ShowType[] = ['text', 'error', 'code', 'markdown', 'html']

function validateAndBuildEntry(item: Record<string, unknown>, dir: string): string | ShowEntry {
  const type = item.type as ShowType | undefined
  if (!type || !TYPES.includes(type as ShowType)) {
    return `'type' is required. Use one of: ${TYPES.join(', ')}.`
  }

  if (PATH_TYPES.includes(type) && !item.path) {
    return `'path' is required when type is '${type}'.`
  }
  if (type === 'url' && !item.url) {
    return `'url' is required when type is 'url'.`
  }
  if (CONTENT_TYPES.includes(type) && !item.content) {
    return `'content' is required when type is '${type}'.`
  }

  if (PATH_TYPES.includes(type) && item.path) {
    const absPath = resolve(dir, item.path as string)
    if (!existsSync(absPath)) {
      return `File not found: ${absPath}`
    }
  }

  const variant = (item.variant as ShowVariant) || undefined
  if (variant && !VARIANTS.includes(variant)) {
    return `Invalid variant '${variant}'. Use one of: ${VARIANTS.join(', ')}.`
  }

  const aspectRatio = (item.aspect_ratio as ShowAspectRatio) || undefined
  if (aspectRatio && !ASPECT_RATIOS.includes(aspectRatio)) {
    return `Invalid aspect_ratio '${aspectRatio}'. Use one of: ${ASPECT_RATIOS.join(', ')}.`
  }

  const theme = (item.theme as ShowTheme) || undefined
  if (theme && !THEMES.includes(theme)) {
    return `Invalid theme '${theme}'. Use one of: ${THEMES.join(', ')}.`
  }

  let metadata: Record<string, unknown> | undefined
  if (item.metadata) {
    if (typeof item.metadata === 'string') {
      try {
        metadata = JSON.parse(item.metadata)
      } catch {
        return `Invalid JSON in 'metadata' parameter.`
      }
    } else if (typeof item.metadata === 'object') {
      metadata = item.metadata as Record<string, unknown>
    }
  }

  const resolvedVariant = variant || defaultVariant(type)

  return {
    id: generateId(),
    timestamp: new Date().toISOString(),
    type,
    variant: resolvedVariant,
    ...(item.title ? { title: item.title as string } : {}),
    ...(item.description ? { description: item.description as string } : {}),
    ...(item.path ? { path: resolve(dir, item.path as string) } : {}),
    ...(item.url ? { url: item.url as string } : {}),
    ...(item.content ? { content: item.content as string } : {}),
    ...(aspectRatio ? { aspect_ratio: aspectRatio } : {}),
    ...(theme && theme !== 'default' ? { theme } : {}),
    ...(item.language ? { language: item.language as string } : {}),
    ...(metadata ? { metadata } : {}),
  }
}

// ── Image digests ──────────────────────────────────────────────────────────

const IMAGE_EXTENSIONS = new Set(['.png', '.jpg', '.jpeg', '.webp', '.gif', '.avif', '.svg'])
const MAX_HASH_BYTES = 32 * 1024 * 1024
const HASH_TIMEOUT_MS = 2_000

/** The sha256 of an image file of at most 32 MiB, streamed; undefined for anything else, a read error or the deadline. */
async function imageSha256(path: string, signal: AbortSignal): Promise<string | undefined> {
  if (!IMAGE_EXTENSIONS.has(extname(path).toLowerCase())) return undefined
  try {
    const info = await stat(path)
    if (!info.isFile() || info.size > MAX_HASH_BYTES) return undefined
    const hash = createHash('sha256')
    let read = 0
    // `end` is inclusive: a file that grew past the cap after stat reads one byte over and is skipped.
    for await (const chunk of createReadStream(path, { end: MAX_HASH_BYTES, signal })) {
      read += chunk.length
      if (read > MAX_HASH_BYTES) return undefined
      hash.update(chunk)
    }
    return hash.digest('hex')
  } catch {
    return undefined
  }
}

/**
 * Add `sha256` to each image entry, all at once. Waits at most HASH_TIMEOUT_MS: `stat` takes no
 * signal and an aborted stream waits for its in-flight read, so the work races the deadline and
 * only digests ready before it are written. Late work settles on its own (imageSha256 never rejects).
 */
async function addImageDigests(entries: ShowEntry[]): Promise<void> {
  const signal = AbortSignal.timeout(HASH_TIMEOUT_MS)
  const digests = new Map<ShowEntry, string>()
  const work = Promise.all(
    entries.map(async (entry) => {
      const sha256 = entry.path ? await imageSha256(entry.path, signal) : undefined
      if (sha256 && !signal.aborted) digests.set(entry, sha256)
    }),
  )
  const deadline = new Promise<void>((done) => (signal.aborted ? done() : signal.addEventListener('abort', () => done(), { once: true })))
  await Promise.race([work, deadline])
  for (const [entry, sha256] of digests) entry.sha256 = sha256
}

// ── Tool definition ────────────────────────────────────────────────────────

const SERVE_EXAMPLE = '`nohup python3 -m http.server 3000 --directory /workspace/site >/tmp/site.log 2>&1 &`'

const showParameters = {
  type: 'object',
  properties: {
    action: { type: 'string', description: "Action: 'show' to present an item to the user." },
    type: {
      type: 'string',
      description:
        "Type of item. Required for single-item 'show' (omit when using 'items'). " +
        "Options: 'file' (any file on disk), 'image' (image file), 'url' (web link or localhost preview), " +
        "'text' (inline text), 'error' (error message), 'video' (video file), 'audio' (audio file), " +
        "'code' (syntax-highlighted code block), 'markdown' (rendered markdown), " +
        "'pdf' (PDF document), 'html' (raw HTML rendered in sandboxed iframe), " +
        "'csv' (CSV/TSV tabular data), 'xlsx' (Excel spreadsheet), " +
        "'docx' (Word document), 'pptx' (PowerPoint presentation).",
    },
    title: { type: 'string', description: "Short heading. E.g. 'Generated Logo', 'API Response', 'Build Output'." },
    description: { type: 'string', description: "Longer description shown below the title. E.g. 'A 1024x1024 logo in your brand colors'." },
    path: {
      type: 'string',
      description:
        "Absolute file path. Required when type is 'file', 'image', 'video', 'audio', 'pdf', 'csv', 'xlsx', 'docx', or 'pptx'. " +
        "E.g. '/workspace/output/logo.png'. Note: passing a .html path as type='file' does not host/execute it; " +
        `serve it with a local web server (e.g. ${SERVE_EXAMPLE} with bash) and pass its ` +
        "plain http://localhost:PORT/ URL as type='url' for live HTML pages.",
    },
    url: {
      type: 'string',
      description:
        "URL to show. Required when type is 'url'. Use for localhost previews (e.g. 'http://localhost:3000') " +
