    },
    content: {
      type: 'string',
      description:
        "Inline content for display. Required when type is 'text', 'error', 'code', 'markdown', or 'html'. " +
        'Use this to communicate information briefly — not to author full artifacts from scratch. ' +
        "If the content is a new document you're creating (spec, report, plan, etc.), write it to a file first and use type='file' with path. " +
        "For 'html', inline HTML rendered in a sandboxed iframe (not a file path).",
    },
    variant: {
      type: 'string',
      description:
        'Display variant controlling the layout. Options: ' +
        "'compact' (minimal inline card), 'full' (fills available space — great for previews), " +
        "'gallery' (visual-first, centered with aspect ratio — great for images/video), " +
        "'detail' (rich layout with prominent title, description, content). " +
        'Smart defaults per type if omitted.',
    },
    aspect_ratio: {
      type: 'string',
      description:
        "Aspect ratio for visual content. Options: 'auto' (default), '1:1', '16:9', '9:16', '4:3', '3:2', '21:9'. " +
        "Most useful with type='image' or type='video' + variant='gallery'.",
    },
    theme: {
      type: 'string',
      description:
        "Visual accent theme. Options: 'default', 'success' (green), 'warning' (amber), " +
        "'info' (blue), 'danger' (red). Affects the border/badge colors.",
    },
    language: {
      type: 'string',
      description: "Programming language for syntax highlighting. Only used when type='code'. " + "E.g. 'python', 'typescript', 'rust', 'json', 'bash'.",
    },
    metadata: { type: 'string', description: 'Optional JSON string of extra metadata. E.g. \'{"width":1024,"format":"png","duration":"3:42"}\'.' },
    items: {
      type: 'string',
      description:
        'JSON array of items to show as a carousel. Each item is an object with: ' +
        'type (required), title, description, path, url, content, variant, aspect_ratio, theme, language, metadata. ' +
        'When provided, individual type/path/url/content params are ignored. ' +
        'Example: \'[{"type":"image","title":"Logo v1","path":"/workspace/v1.png"},{"type":"image","title":"Logo v2","path":"/workspace/v2.png"}]\'',
    },
  },
  required: ['action'],
}

const shown = (value: unknown) => JSON.stringify(value, null, 2)

/** A relative `path` resolves against the project checkout (`context.directory`). */
export default {
  description:
    'Show outputs and attachments to the human user. This tool PRESENTS and DISPLAYS existing content — ' +
    'it is NOT a place to author or store artifacts. Show should SHOW, not be where you write.\n\n' +
    'CRITICAL RULE: Do not use show to write new artifacts from scratch. If you need to create a ' +
    'spec, report, plan, document, config, or any authored content — write it to a file first ' +
    "using the write tool, then present it with show(type='file', path='...'). " +
    "The 'content' parameter is for communicating brief information inline (status, summaries, " +
    'snippets, errors, previews) — not for authoring documents.\n\n' +
    "Good: Write spec to /workspace/spec.md → show(type='file', path='/workspace/spec.md')\n" +
    "Good: show(type='text', content='Build succeeded in 3.2s')\n" +
    "Good: show(type='code', content='const x = 1;', language='typescript')\n" +
    "Bad: show(type='markdown', content='# Full spec written from scratch here...') — write to file first!\n\n" +
    'Types: file, image, url, text, error, video, audio, code, markdown, pdf, html, csv, xlsx, docx, pptx.\n' +
    "IMPORTANT HTML NOTE: type='html' renders INLINE HTML from the 'content' field only. " +
    'A standalone .html file or website on disk is NOT auto-hosted — serve it with a local web server, ' +
    "then pass its plain URL with type='url'. For a static site, start one in the background with bash " +
    `(e.g. ${SERVE_EXAMPLE}); for an app, run its dev server the same way ` +
    "(e.g. `npm run dev`). Then show(type='url', url='http://localhost:3000/'). The platform auto-detects " +
    'and proxies any localhost port — just use a plain http://localhost:PORT/ URL, no special path format needed.\n' +
    'Variants (display hints): compact, full, gallery, detail — controls layout. ' +
    'Defaults are smart per type but can be overridden.\n' +
    'aspect_ratio: auto, 1:1, 16:9, 9:16, 4:3, 3:2, 21:9 — for visual content.\n' +
    'theme: default, success, warning, info, danger — visual accent.\n' +
    "language: for type='code', the language for syntax highlighting (e.g. 'python', 'typescript').\n\n" +
    'MULTI-ITEM MODE: To show multiple items at once (rendered as a carousel), pass a JSON array ' +
    "string to the 'items' parameter instead of individual type/path/url/content params. " +
    'Each item in the array is an object with the same fields (type, title, path, url, content, etc.).\n' +
    'When you have 2 or more outputs to present together (several screenshots, a page and its docs, ' +
    "v1 and v2 of a design), make ONE show call with 'items' — not one show call per output. " +
    'Give each item its own title so the user can tell them apart while paging.',
  parameters: showParameters,
  async execute(args: Record<string, any>, { directory: dir }: ToolContext): Promise<string> {
    let parsed: unknown = null
    if (args.items) {
      try {
        parsed = JSON.parse(args.items)
      } catch {
        throw new Error("Invalid JSON in 'items' parameter. Must be a JSON array of objects.")
      }
    }
    // A model fills the unused optional `items` with "null" or "[]" beside a single item: that is single-item mode.
    if (parsed !== null && !(Array.isArray(parsed) && parsed.length === 0)) {
      if (!Array.isArray(parsed)) throw new Error("'items' must be a non-empty JSON array.")
      const entries: ShowEntry[] = []
      const errors: string[] = []
      parsed.forEach((item, i) => {
        const result = item && typeof item === 'object' ? validateAndBuildEntry(item as Record<string, unknown>, dir) : 'must be an object.'
        if (typeof result === 'string') errors.push(`Item ${i}: ${result}`)
        else entries.push(result)
      })
      if (entries.length === 0) throw new Error(`All items failed validation:\n${errors.join('\n')}`)
      await addImageDigests(entries)
      return shown({
        success: true,
        action: 'show',
        ...(args.title && { title: args.title }),
        ...(args.description && { description: args.description }),
        ...(args.theme && args.theme !== 'default' && { theme: args.theme }),
        items: entries,
        ...(errors.length > 0 && { warnings: errors }),
        message: `${entries.length} item(s) presented to user as carousel.`,
      })
    }
    const entry = validateAndBuildEntry(args, dir)
    if (typeof entry === 'string') throw new Error(entry)
    await addImageDigests([entry])
    return shown({ success: true, action: 'show', entry, message: `Item '${args.title || args.type}' presented to user.` })
  },
}

web_search:
/**
 * web_search: the Kortix web search tool (Tavily). Kortix maintains this file,
 * and every session loads it; an agent's `tools` grant decides whether that
 * agent can call it. `kortix tools eject web_search` copies it to `tools/web_search.ts` for the
 * project to own and change; the copy runs unchanged on every harness.
 *
 * A call goes to the Kortix API's billed router proxy with the session token
 * (`KORTIX_API_URL`, `KORTIX_TOKEN`); the router holds the Tavily key. A box
 * with no Kortix API calls Tavily itself with `TAVILY_API_KEY`.
 *
 * The web UI renders a call from the output JSON. A changed copy must keep
 * that shape, or the UI shows the raw output.
 */

/** What a call receives (the project tool contract): the session env, secrets included, and the turn's abort signal. */
interface ToolContext {
  env: Record<string, string | undefined>
  signal?: AbortSignal
}

const TIMEOUT_MS = 60_000

/** The Kortix router proxy and the session token, or Tavily and the project's own key. */
function upstream(env: ToolContext['env']): { base: string; key: string } {
  const api = env.KORTIX_API_URL?.trim().replace(/\/+$/, '')
  if (api) {
    const token = env.KORTIX_TOKEN?.trim()
    if (!token) throw new Error('KORTIX_TOKEN is not set.')
    return { base: `${api.endsWith('/v1') ? api : `${api}/v1`}/router/tavily`, key: token }
  }
  const key = env.TAVILY_API_KEY?.trim()
  if (!key) throw new Error('TAVILY_API_KEY is not set.')
  return { base: 'https://api.tavily.com', key }
}

type TavilyResponse = {
  answer?: string
  results?: Array<{ title?: string; url?: string; content?: string; score?: number; published_date?: string }>
  images?: Array<string | { url?: string; description?: string }>
  response_time?: number
}

export default {
  description:
    'Search the web for up-to-date information using Tavily. ' +
    'Returns titles, URLs, snippets, relevance scores, images, and a synthesized AI answer. ' +
    'Supports batch queries separated by |||. ' +
    "Use topic='news' for current events, topic='finance' for financial data. " +
    'After using results, ALWAYS include a Sources section with markdown hyperlinks.',
  parameters: {
    type: 'object',
    properties: {
      query: { type: 'string', description: "Search query. For batch, separate with ||| (e.g. 'query one ||| query two')" },
      num_results: { type: 'number', description: 'Results per query (1-20). Default: 5' },
      topic: { type: 'string', description: "Search topic: 'general' (default), 'news', or 'finance'" },
      search_depth: {
        type: 'string',
        description:
          "Search depth: 'basic' (faster, cheaper, default) or 'advanced' (slower, more thorough). Use 'basic' for most queries. Reserve 'advanced' for deep research where comprehensiveness matters.",
      },
    },
    required: ['query'],
  },
  async execute(args: Record<string, any>, { env, signal }: ToolContext): Promise<string> {
    const { base, key } = upstream(env)
    const queries = String(args.query ?? '').split('|||').map((query) => query.trim()).filter(Boolean)
    if (queries.length === 0) throw new Error('The query is empty.')
    const timeout = signal ? AbortSignal.any([signal, AbortSignal.timeout(TIMEOUT_MS)]) : AbortSignal.timeout(TIMEOUT_MS)
    const searchOne = async (query: string) => {
      try {
        const response = await fetch(`${base}/search`, {
          method: 'POST',
          headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
          body: JSON.stringify({
            query,
            search_depth: args.search_depth || 'basic',
            topic: args.topic || 'general',
            max_results: Math.max(1, Math.min(args.num_results ?? 5, 20)),
            include_answer: true,
            include_images: true,
            include_image_descriptions: true,
          }),
          signal: timeout,
        })
        const body = await response.text()
        if (!response.ok) throw new Error(`${response.status} Error: ${body}`)
        const data = JSON.parse(body) as TavilyResponse
        const results = data.results ?? []
        return {
          query,
          success: results.length > 0 || !!data.answer,
          answer: data.answer ?? '',
          results: results.map((r) => ({
            title: r.title ?? '',
            url: r.url ?? '',
            snippet: r.content ?? '',
            score: r.score ?? 0,
            published_date: r.published_date ?? '',
          })),
          images: (data.images ?? []).map((image) =>
            typeof image === 'string' ? { url: image, description: '' } : { url: image.url ?? '', description: image.description ?? '' },
          ),
          response_time_ms: data.response_time,
        }
      } catch (err) {
        return { query, success: false, error: String(err) }
      }
    }
    const results = await Promise.all(queries.map(searchOne))
    if (results.length === 1) return JSON.stringify(results[0], null, 2)
    return JSON.stringify({ batch_mode: true, total_queries: queries.length, results }, null, 2)
  },
}
